use crate::pic::{PlaneQuartic,PicClass,Pt};
use hec_native_ic::{fp::Fp,poly::Poly,rng::Rng,solve::{Row,SolveStats,Solver,solve_for_last}};
use std::collections::HashMap;
pub struct Base{points:Vec<Pt>,conics:Vec<Vec<u64>>,ids:HashMap<Pt,usize>,rows:Vec<(Row,u64)>,pub lines:usize,pub split_lines:usize,pub relation_pic_cost:crate::pic::FqCounter}
fn form(terms:&[(usize,i64)],ell:u64)->Row{let f=Fp::new(ell);let mut m=std::collections::BTreeMap::new();for &(i,c)in terms{let v=m.entry(i).or_insert(0);*v=f.add(*v,f.from_i64(c));}m.into_iter().filter(|(_,v)|*v!=0).map(|(i,v)|(i as u32,v)).collect()}
fn line_polynomial(pc:&PlaneQuartic,line:Pt,f:&Fp)->(Poly,Pt){let(u,v)=if line[0]!=0{([f.neg(line[1]),1,0],[f.neg(line[2]),0,1])}else if line[1]!=0{([1,0,0],[0,f.neg(line[2]),1])}else{([1,0,0],[0,1,0])};let coords=(0..3).map(|i|Poly::from_coeffs(&[v[i],u[i]])).collect::<Vec<_>>();let mut p=Poly::zero();for(&(i,j,k),&a)in crate::pic::mons_of_degree(4).iter().zip(pc.coefficients()){let mut t=Poly::constant(a);for(axis,n)in[i,j,k].iter().enumerate(){for _ in 0..*n{t=t.mul(&coords[axis],f);}}p=p.add(&t,f);}assert!(!p.is_zero());(p,pc.normalize_point(u))}
pub fn build(pc:&PlaneQuartic,ell:u64,map:usize)->Base{let before=pc.counter();let f=Fp::new(pc.q());let points=pc.rational_points_bruteforce();assert_eq!(points.len(),66);let ids=points.iter().enumerate().map(|(i,&p)|(p,i)).collect::<HashMap<_,_>>();let conics=points.iter().map(|&p|pc.std_values(2,p)).collect();let point_classes=points.iter().map(|&p|pc.point_class(p)).collect::<Vec<_>>();let mut rows=Vec::new();let p0=*ids.get(&pc.base_point()).unwrap();rows.push((vec![(p0 as u32,1)],0));let mut lines=0;let mut split_lines=0;let mut kappa=None;let line_list=(0..pc.q()).flat_map(|b|(0..pc.q()).map(move|c|[1,b,c])).chain((0..pc.q()).map(|c|[0,1,c])).chain(std::iter::once([0,0,1]));for line in line_list{lines+=1;let(mut p,infinity)=line_polynomial(pc,line,&f);let mut divisor=Vec::new();let missing=4-p.deg()as usize;if missing>0{divisor.push((*ids.get(&infinity).unwrap(),missing));}for t in 0..pc.q(){let mut multiplicity=0;while p.deg()>0&&p.eval(t,&f)==0{p=p.div_exact(&Poly::x_minus(t,&f),&f);multiplicity+=1;}if multiplicity>0{let pt=if line[0]!=0{pc.normalize_point([f.neg(f.add(f.mul(line[1],t),line[2])),t,1])}else if line[1]!=0{pc.normalize_point([t,f.neg(line[2]),1])}else{pc.normalize_point([t,1,0])};assert_eq!((0..3).fold(0,|s,i|f.add(s,f.mul(line[i],pt[i]))),0);let id=*ids.get(&pt).unwrap();divisor.push((id,multiplicity));}}if p.deg()!=0{continue;}assert_eq!(divisor.iter().map(|x|x.1).sum::<usize>(),4);let sum=divisor.iter().fold(pc.zero(),|s,&(id,m)|pc.add(&s,&pc.mul_scalar(&point_classes[id],m as u128)));if let Some(ref expected)=kappa{assert_eq!(&sum,expected,"line relation class mismatch");}else{kappa=Some(sum);}let mut terms=divisor.iter().map(|&(i,n)|(i,n as i64)).collect::<Vec<_>>();terms.push((points.len(),-1));rows.push((form(&terms,ell),0));split_lines+=1;println!("LINE map={map} coefficients={line:?} support={divisor:?}");}assert_eq!(lines,3783);assert!(split_lines>0);println!("BASE map={map} points={} lines={lines} split_lines={split_lines} line_class_relations_verified=true",points.len());Base{points,conics,ids,rows,lines,split_lines,relation_pic_cost:pc.counter().since(&before)}}
fn decompose(pc:&PlaneQuartic,x:&PicClass,base:&Base)->Option<Vec<(usize,i64)>>{match x{PicClass::Exc(p)=>Some(vec![(*base.ids.get(p)?, -1)]),PicClass::Typ(rows)=>{let f=Fp::new(pc.q());let roots=base.conics.iter().enumerate().filter(|(_,v)|rows.iter().all(|r|r.iter().zip(v.iter()).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b)))==0)).map(|(i,_)|i).collect::<Vec<_>>();if roots.len()!=3{return None;}let mut out=roots.into_iter().map(|i|(i,1)).collect::<Vec<_>>();out.push((base.points.len(),-1));Some(out)}}}
#[derive(Debug)]pub struct Report{pub k:u64,pub trials:usize,pub smooth:usize,pub relations:usize,pub solve_rounds:usize,pub solver:SolveStats,pub pic_cost:crate::pic::FqCounter}
pub fn solve(pc:&PlaneQuartic,g:&PicClass,t:&PicClass,ell:u64,base:&Base,seed:u64)->Option<Report>{let start=pc.counter();assert!(!pc.is_zero(g));assert!(ell*ell>9u64.pow(6));assert!(pc.is_zero(&pc.mul_scalar(g,ell as u128)));assert!(pc.is_zero(&pc.mul_scalar(t,ell as u128)));let mut rng=Rng::new(seed);let fl=Fp::new(ell);let mut x=pc.zero();let(mut a,mut b)=(0,0);let mut rows=base.rows.clone();let mut smooth=0;let mut rounds=0;let mut all_stats=SolveStats::default();for trial in 1..=4096{if rng.below(2)==0{x=pc.add(&x,g);a=fl.add(a,1);}else{x=pc.add(&x,t);b=fl.add(b,1);}let Some(mut terms)=decompose(pc,&x,base)else{continue;};smooth+=1;terms.push((base.points.len()+1,-(b as i64)));let row=form(&terms,ell);rows.push((row,a));rounds+=1;let mut stats=SolveStats::default();let k=solve_for_last(&rows,base.points.len()+1,ell,Solver::Fast,&[],&mut stats);all_stats.pivots+=stats.pivots;all_stats.row_ops+=stats.row_ops;all_stats.mulmods+=stats.mulmods;all_stats.max_row_len=all_stats.max_row_len.max(stats.max_row_len);all_stats.pivot_hash=stats.pivot_hash;if let Some(k)=k{assert_eq!(pc.mul_scalar(g,k as u128),*t,"quartic final verification failed");return Some(Report{k,trials:trial,smooth,relations:rows.len(),solve_rounds:rounds,solver:all_stats,pic_cost:pc.counter().since(&start)});}}None}
